package com.gameaggregator.gameservice.api;import com.gameaggregator.platform.core.common.web.ApiResponse;import com.gameaggregator.gameservice.application.GameService;import com.gameaggregator.gameservice.domain.*;import jakarta.validation.Valid;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1") public class GameController{final GameService s;public GameController(GameService s){this.s=s;}@PostMapping("/games")ApiResponse<Game> create(@Valid @RequestBody GameDtos.Create r){return ApiResponse.success(s.create(r));}@GetMapping("/games")ApiResponse<List<Game>> list(){return ApiResponse.success(s.list());}@GetMapping("/games/{id}")ApiResponse<Game> get(@PathVariable UUID id){return ApiResponse.success(s.get(id));}@PutMapping("/games/{id}")ApiResponse<Game> update(@PathVariable UUID id,@Valid @RequestBody GameDtos.Update r){return ApiResponse.success(s.update(id,r));}@PostMapping("/games/{id}/archive")ApiResponse<Game> archive(@PathVariable UUID id){return ApiResponse.success(s.archive(id));}@PostMapping("/taxonomies")ApiResponse<Taxonomy> taxonomy(@Valid @RequestBody GameDtos.Classification r){return ApiResponse.success(s.taxonomy(r));}@GetMapping("/taxonomies")ApiResponse<List<Taxonomy>> taxonomies(@RequestParam(required=false)String type){return ApiResponse.success(s.taxonomies(type));}@PostMapping("/games/{id}/classifications")ApiResponse<GameTaxonomy> attach(@PathVariable UUID id,@Valid @RequestBody GameDtos.Attach r){return ApiResponse.success(s.attach(id,r));}}